const D = { energy: .6, scale: 1, density: .45, depth: .62, sharp: .55, hue: 192, speed: 1, x: .5, y: .8, alpha: .92, style: 'sunlit', act: 'drift', seed: 0 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const cl=(v,a,b)=>v<a?a:v>b?b:v, md=(a,n)=>((a%n)+n)%n, TAU=Math.PI*2;
const ss=(e0,e1,x)=>{let t=(x-e0)/(e1-e0); t=t<0?0:t>1?1:t; return t*t*(3-2*t);};
const fr=i=>{const s=Math.sin(i*127.1+P.seed*311.7)*43758.5453;return s-Math.floor(s);};
const hsb=(h,s,b)=>{ h=md(h,360)/60; s=cl(s,0,100)/100; b=cl(b,0,100)/100;
  const c=b*s, x=c*(1-Math.abs((h%2)-1)), m=b-c; let r,g,l;
  if(h<1){r=c;g=x;l=0;} else if(h<2){r=x;g=c;l=0;} else if(h<3){r=0;g=c;l=x;}
  else if(h<4){r=0;g=x;l=c;} else if(h<5){r=x;g=0;l=c;} else {r=c;g=0;l=x;}
  return [(r+m)*255|0,(g+m)*255|0,(l+m)*255|0]; };
if(S.lastBeat==null||K.beat<S.lastBeat)S.lastBeat=K.beat; S.lastBeat=K.beat;
if(!S.sinT){ const L=new Float32Array(2048); for(let i=0;i<2048;i++) L[i]=Math.sin(i/2048*TAU); S.sinT=L; }
const ST=S.sinT, SN=a=>ST[(((a*325.949323)|0)&2047)];

const W=width, Hh=height, u=Math.min(W,Hh), dc=drawingContext, oldOp=dc.globalCompositeOperation;
const styN=P.style, act=P.act;
const en=cl(P.energy,0,1), sc=cl(P.scale,.3,2.4), dns=cl(P.density,0,1);
const dp0=cl(P.depth,0,1), shp=cl(P.sharp,0,1), H0=md(P.hue,360);
const spd=cl(P.speed,.1,4), al=cl(P.alpha,0,1), ax=cl(P.x,0,1), ay=cl(P.y,0,1);
const T=K.t*(.28+.72*spd);
const MODE = styN==='deep'?1 : styN==='murky'?2 : styN==='pool'?3 : styN==='under_ice'?4 : 0;

S.rms=(S.rms||0)*.92+(A.rms||0)*.08;
S.low=(S.low||0)*.92+(A.lowmid||0)*.08;

// ---- dramaturgy over minutes ----
let dp=dp0, chop=1, sink=0;
if(act==='swell'){ chop=.55+1.35*(.5+.5*Math.sin(K.t*.021)); }               // the chop builds and eases
else if(act==='descend'){ const q=md(K.t*.0055,1); sink=q; dp=cl(dp0*(.55+1.30*q),0,1); chop=1.15-.55*q; }
else { chop=.85+.35*Math.sin(K.t*.033)+.18*Math.sin(K.t*.079+1.2); }
chop*=(.7+.55*K.intensity);

// per-style physics: what makes the image, not just the hue
// ambG = the broad ambient scatter of the water body itself. Caustic veins are
// mathematically sparse (mean of pow(1-ridge,~5) is ~1e-3) and can never carry
// luminance or the motion floor alone — the ambient field is what makes this read.
let pw=1.8+shp*5.5, caGain=1.0, absG=1.0, turbG=1.0, surfG=1.0, ambG=1.0, hueW=H0;
if(MODE===1){ pw=1.6+shp*3.6; caGain=.52; absG=1.55; turbG=1.20; surfG=.42; ambG=.62; hueW=md(H0+16,360); }
else if(MODE===2){ pw=1.3+shp*2.6; caGain=.42; absG=1.30; turbG=1.70; surfG=.55; ambG=.98; hueW=md(H0-118,360); }
else if(MODE===3){ pw=3.2+shp*8.0; caGain=1.65; absG=.42; turbG=.35; surfG=1.15; ambG=1.05; hueW=md(H0-6,360); }
else if(MODE===4){ pw=1.8+shp*4.0; caGain=.60; absG=.85; turbG=.75; surfG=.95; ambG=.92; hueW=md(H0+8,360); }

let GW,GH;
if(W>=Hh){ GW=160; GH=Math.max(56,Math.round(160*Hh/Math.max(1,W))); }
else { GH=160; GW=Math.max(56,Math.round(160*W/Math.max(1,Hh))); }
const gk=GW+'x'+GH;
if(!S.eB||S.gk!==gk){
  if(S.eB&&S.eB.remove)S.eB.remove(); if(S.mB&&S.mB.remove)S.mB.remove();
  S.eB=createGraphics(GW,GH); S.eB.pixelDensity(1);
  S.mB=createGraphics(GW,GH); S.mB.pixelDensity(1);
  S.gk=gk;
}
const eB=S.eB, mB=S.mB;
eB.loadPixels(); mB.loadPixels();
const pE=eB.pixels, pM=mB.pixels;

const zoom=(2.6/(.35+sc*1.05))*(1+.5*sink);
const ox=fr(1)*30+ (ax-.5)*5.2 + T*.045;                 // a slow lateral swim: never repeats
const oy=fr(2)*30 - T*.026 + sink*2.2;
const surf0=(ay-.85)*Hh;
const cCau = hsb(md(hueW-14,360), MODE===2?38:MODE===3?12:26, 100);
const cWat = hsb(hueW, MODE===2?62:78, 100);
const cTur = hsb(md(hueW+(MODE===2?-16:10),360), MODE===2?46:30, 100);
const gainE=(.42+.92*en)*al*(1+.10*S.rms);

for(let j=0;j<GH;j++){
  const yy=(j+.5)/GH*Hh;
  const ny=(yy/Hh-.5)*zoom+oy;
  for(let i=0;i<GW;i++){
    const xx=(i+.5)/GW*W;
    const nx=(xx/W-.5)*zoom*(W/Math.max(1,Hh))+ox;
    const o=(j*GW+i)*4;

    // ---- the surface, undulating overhead ----
    const rip=(SN(nx*3.1+T*.62)*.55+SN(nx*5.7-T*.41)*.30+SN(nx*1.3+T*.23)*.28)*chop;
    const sY=surf0 + rip*u*(MODE===4?.012:.030);
    const below=ss(sY-u*.004, sY+u*.004, yy);
    const sdst=(yy-sY)/(u*.11);
    const surfBand=Math.exp(-sdst*sdst*.60)*surfG;

    // depth below the surface drives everything
    const dn=cl((yy-sY)/(Hh*1.30),0,1);

    // ---- caustics: ridge interference, warped on incommensurate rates ----
    const w1=SN(ny*1.63+T*.29)*.52+SN(nx*.91-T*.21)*.31;
    const w2=SN(nx*1.87-T*.25)*.52+SN(ny*1.09+T*.33)*.31;
    const a1=SN((nx+1.35*w1*chop)*3.3+T*1.05);
    const a2=SN((ny+1.35*w2*chop)*3.1-T*.87);
    const a3=SN((nx+ny+1.1*(w1+w2)*chop)*2.2+T*.66);
    const ridge=(Math.abs(a1)+Math.abs(a2)+Math.abs(a3))/3;
    let caust=Math.pow(cl(1-ridge,0,1),pw)*1.75*caGain;
    caust*=Math.exp(-dn*dp*1.35)*below;                    // light runs out with depth

    // under ice: the ceiling is a frozen crack net, not a rippling skin
    let ice=0;
    if(MODE===4){
      const cr=Math.pow(cl(1-Math.abs(SN((nx+.7*w1)*2.4)+SN((ny+.7*w2)*2.1))*.85,0,1),3.2);
      ice=cr*Math.exp(-Math.max(0,(yy-sY))/(u*.34))*.85;
    }

    // ---- turbidity: a broad scattering haze. This is the area element that keeps
    // the pass from being fine-detail-only (sparse detail cannot carry the gate) ----
    const turb=dns*turbG*(.08+.42*dn)*(.55+.45*SN(nx*1.1+ny*.7+T*.13))*below;

    // the water body itself glows — a broad field, brightest just under the skin,
    // running out with depth. This is the area element the gate actually sees.
    const amb=below*ambG*(.085+.275*Math.exp(-dn*dp*1.05))*(.85+.30*SN(nx*.63+ny*.44-T*.09));
    let e = amb*(.55+.75*en) + caust*(.34+.95*en) + surfBand*(.22+.40*en)*(1-dn*.5)
          + turb*.32 + ice*(.3+.7*en);
    e += (1-below)*(.30+.30*en);                           // air above the surface stays open
    e *= gainE;

    let cR,cG,cB;
    if(surfBand>.42||(1-below)>.5){ cR=cCau[0]; cG=cCau[1]; cB=cCau[2]; }
    else if(turb*.32>caust*(.34+.95*en)){ cR=cTur[0]; cG=cTur[1]; cB=cTur[2]; }
    else {
      // veins read as sunlight; the ambient body reads as water — mix by who is winning
      const vw=cl(caust*(.34+.95*en)/Math.max(1e-4,caust*(.34+.95*en)+amb*(.55+.75*en)),0,1);
      cR=cCau[0]*vw+cWat[0]*(1-vw); cG=cCau[1]*vw+cWat[1]*(1-vw); cB=cCau[2]*vw+cWat[2]*(1-vw);
    }
    pE[o]=cl(cR*e,0,255); pE[o+1]=cl(cG*e,0,255); pE[o+2]=cl(cB*e,0,255); pE[o+3]=255;

    // ---- absorption: water eats red first, then green. This is the depth cue. ----
    const q=dn*dp*absG*below;
    const aR=Math.exp(-q*3.30), aG=Math.exp(-q*1.28), aB=Math.exp(-q*.52);
    const hs=(hueW-192)/360;                               // let hue steer which channel survives
    pM[o]=255*cl(aR*(1-hs*.5),0,1); pM[o+1]=255*cl(aG,0,1); pM[o+2]=255*cl(aB*(1+hs*.3),0,1); pM[o+3]=255;
  }
}
