    const w1=.037+.061*fr(i*5+1), w2=.029+.053*fr(i*5+3);
    const px=md(fr(i*5+2)*W + Math.sin(T*w1+i)*u*.07 + T*3.1*(.3+fr(i*5+4)), W);
    const py=md(fr(i*5+5)*Hh - T*1.4*(.4+fr(i*5+6)) + Math.sin(T*w2+i*1.7)*u*.05, Hh);
    const r=u*(.0016+.0042*fr(i*5+7));
    circle(px,py,r*2);
  }
}

